static int em28xx_ir_resume ( struct em28xx * dev ) { struct em28xx_IR * ir = dev -> ir ; dev_info ( & dev -> intf -> dev , "Resuming input extension\n" ) ; if ( ir ) { schedule_delayed_work ( & ir -> work , msecs_to_jiffies ( ir -> polling ) ) ; } if ( dev -> num_button_polling_addresses ) { schedule_delayed_work ( & dev -> buttons_query_work , msecs_to_jiffies ( dev -> button_polling_interval ) ) ; } return 0 ; } 